CustomField.formula:
IF( Shift_Category__c = "Custom",
( /* Morning */ IF( OR(ISBLANK(Long_Morning_Start_Time__c),ISBLANK(Long_Morning_End_Time__c)),0, IF(Long_Morning_End_Time__c >= Long_Morning_Start_Time__c, ((HOUR(Long_Morning_End_Time__c)*60+MINUTE(Long_Morning_End_Time__c))- (HOUR(Long_Morning_Start_Time__c)*60+MINUTE(Long_Morning_Start_Time__c)))/60, ((HOUR(Long_Morning_End_Time__c)*60+MINUTE(Long_Morning_End_Time__c))+1440- (HOUR(Long_Morning_Start_Time__c)*60+MINUTE(Long_Morning_Start_Time__c)))/60 ) * BLANKVALUE(Long_Morning_Hourly_Rate__c,0))
+
/* Afternoon */ IF( OR(ISBLANK(Long_Afternoon_Start_Time__c),ISBLANK(Long_Afternoon_End_Time__c)),0, IF(Long_Afternoon_End_Time__c >= Long_Afternoon_Start_Time__c, ((HOUR(Long_Afternoon_End_Time__c)*60+MINUTE(Long_Afternoon_End_Time__c))- (HOUR(Long_Afternoon_Start_Time__c)*60+MINUTE(Long_Afternoon_Start_Time__c)))/60, ((HOUR(Long_Afternoon_End_Time__c)*60+MINUTE(Long_Afternoon_End_Time__c))+1440- (HOUR(Long_Afternoon_Start_Time__c)*60+MINUTE(Long_Afternoon_Start_Time__c)))/60 ) * BLANKVALUE(Long_Afternoon_Hourly_Rate__c,0))
+
/* Night */ IF( OR(ISBLANK(Long_Night_Start_Time__c),ISBLANK(Long_Night_End_Time__c)),0, IF(Long_Night_End_Time__c >= Long_Night_Start_Time__c, ((HOUR(Long_Night_End_Time__c)*60+MINUTE(Long_Night_End_Time__c))- (HOUR(Long_Night_Start_Time__c)*60+MINUTE(Long_Night_Start_Time__c)))/60, ((HOUR(Long_Night_End_Time__c)*60+MINUTE(Long_Night_End_Time__c))+1440- (HOUR(Long_Night_Start_Time__c)*60+MINUTE(Long_Night_Start_Time__c)))/60 ) * BLANKVALUE(Long_Night_Hourly_Rate__c,0))
+
/* Morning Two */ IF( OR(ISBLANK(Long_Morning_Start_Time_Two__c),ISBLANK(Long_Morning_End_Time_Two__c)),0, IF(Long_Morning_End_Time_Two__c >= Long_Morning_Start_Time_Two__c, ((HOUR(Long_Morning_End_Time_Two__c)*60+MINUTE(Long_Morning_End_Time_Two__c))- (HOUR(Long_Morning_Start_Time_Two__c)*60+MINUTE(Long_Morning_Start_Time_Two__c)))/60, ((HOUR(Long_Morning_End_Time_Two__c)*60+MINUTE(Long_Morning_End_Time_Two__c))+1440- (HOUR(Long_Morning_Start_Time_Two__c)*60+MINUTE(Long_Morning_Start_Time_Two__c)))/60 ) * BLANKVALUE(Long_Morning_Rate_Two__c,0))
+
/* Afternoon Two */ IF( OR(ISBLANK(Long_Afternoon_Start_Time_two__c),ISBLANK(Long_afternoon_End_Time_Two__c)),0, IF(Long_afternoon_End_Time_Two__c >= Long_Afternoon_Start_Time_two__c, ((HOUR(Long_afternoon_End_Time_Two__c)*60+MINUTE(Long_afternoon_End_Time_Two__c))- (HOUR(Long_Afternoon_Start_Time_two__c)*60+MINUTE(Long_Afternoon_Start_Time_two__c)))/60, ((HOUR(Long_afternoon_End_Time_Two__c)*60+MINUTE(Long_afternoon_End_Time_Two__c))+1440- (HOUR(Long_Afternoon_Start_Time_two__c)*60+MINUTE(Long_Afternoon_Start_Time_two__c)))/60 ) * BLANKVALUE(Long_Afternoon_Rate_Two__c,0))
+
BLANKVALUE(Long_Sleepover_Allowance__c,0)
) / Actual_Duration__c,
0 )
